(function(){(()=>{"use strict";const e=(o,t,a,i,n,r)=>({g:o,p:t,n:a,f:i,how:n,ex:r});window.PhysicaRankComplexJee={chapter:"Complex Numbers and Quadratic Equations",secs:["Complex numbers: algebra","Modulus, conjugate and argument","Polar form, De Moivre and roots of unity","Locus and geometry","Quadratic equations: roots and nature","Location of roots and common roots"],table:[["i\xB2 = \u22121","i, i\xB2, i\xB3, i\u2074 = i, \u22121, \u2212i, 1 and then repeats"],["z = x + iy","real part x, imaginary part y"],["|z|, z\u0304","modulus \u221A(x\xB2 + y\xB2), conjugate x \u2212 iy"],["z\xB7z\u0304 = |z|\xB2","product of a number and its conjugate"],["\u03C9","cube root of unity: \u03C9\xB3 = 1, 1 + \u03C9 + \u03C9\xB2 = 0"],["D = b\xB2 \u2212 4ac","discriminant of ax\xB2 + bx + c = 0"]],formulas:[e("Complex numbers: algebra",1,"Powers of i and the basic operations","i\xB2 = \u22121 \xB7 i\u207F depends on n mod 4: i\u2070 = 1, i\xB9 = i, i\xB2 = \u22121, i\xB3 = \u2212i \xB7 (a + ib) + (c + id) = (a + c) + i(b + d) \xB7 (a + ib)(c + id) = (ac \u2212 bd) + i(ad + bc) \xB7 a + ib = c + id \u21D4 a = c and b = d","Divide n by 4 and keep the remainder. For a quotient multiply the top and bottom by the conjugate of the bottom.","i\xB2\u2070\xB2\xB3: 2023 leaves remainder 3 on division by 4, so i\xB2\u2070\xB2\xB3 = i\xB3 = \u2212i. And (3 + 4i)/(1 \u2212 2i) = \u22121 + 2i."),e("Complex numbers: algebra",1,"Square root of a complex number","\u221A(a + ib) = \xB1( \u221A((|z| + a)/2) + i\xB7sign(b)\xB7\u221A((|z| \u2212 a)/2) ) where |z| = \u221A(a\xB2 + b\xB2) \xB7 or put \u221A(a + ib) = x + iy and compare real and imaginary parts","Square x + iy, equate the real and imaginary parts, and use x\xB2 + y\xB2 = |z| as a helper.","\u221A(3 + 4i) = \xB1(2 + i), because (2 + i)\xB2 = 3 + 4i."),e("Modulus, conjugate and argument",1,"Conjugate and modulus","z\u0304 = x \u2212 iy \xB7 z + z\u0304 = 2x \xB7 z \u2212 z\u0304 = 2iy \xB7 z\xB7z\u0304 = |z|\xB2 \xB7 |z\u2081z\u2082| = |z\u2081||z\u2082| \xB7 |z\u2081/z\u2082| = |z\u2081|/|z\u2082| \xB7 |z\u0304| = |z| \xB7 |z\u207F| = |z|\u207F \xB7 conj of a product = product of conjugates \xB7 z is real \u21D4 z = z\u0304 \xB7 z is purely imaginary \u21D4 z + z\u0304 = 0 (and z \u2260 0)","Use z\xB7z\u0304 = |z|\xB2 to remove a modulus or to divide. Use z = z\u0304 to test whether a number is real.","|3 \u2212 4i| = 5 and (3 \u2212 4i)(3 + 4i) = 25."),e("Modulus, conjugate and argument",1,"Triangle inequalities","|z\u2081 + z\u2082| \u2264 |z\u2081| + |z\u2082| \xB7 |z\u2081 \u2212 z\u2082| \u2265 ||z\u2081| \u2212 |z\u2082|| \xB7 |z\u2081 + z\u2082|\xB2 + |z\u2081 \u2212 z\u2082|\xB2 = 2(|z\u2081|\xB2 + |z\u2082|\xB2) \xB7 equality when z\u2081 and z\u2082 have the same direction (first one)","Use them to find the greatest and least value of |z\u2081 + z\u2082| when |z\u2081| and |z\u2082| are given.","If |z\u2081| = 3 and |z\u2082| = 4 then |z\u2081 + z\u2082| lies between 1 and 7."),e("Modulus, conjugate and argument",1,"Argument","arg z = \u03B8 where tan \u03B8 = y/x, with the quadrant of (x, y) \xB7 principal value \u2212\u03C0 < \u03B8 \u2264 \u03C0 \xB7 arg(z\u2081z\u2082) = arg z\u2081 + arg z\u2082 (mod 2\u03C0) \xB7 arg(z\u2081/z\u2082) = arg z\u2081 \u2212 arg z\u2082 \xB7 arg z\u0304 = \u2212 arg z \xB7 arg(\u2212z) = arg z \xB1 \u03C0","Draw the point in the plane first to pick the quadrant, then find the angle from tan\u207B\xB9|y/x|.","arg(\u22121 + i) = 3\u03C0/4, since the point is in the second quadrant with a 45\xB0 slope."),e("Polar form, De Moivre and roots of unity",1,"Polar form and De Moivre","z = r(cos \u03B8 + i sin \u03B8) = r e^{i\u03B8} \xB7 (cos \u03B8 + i sin \u03B8)\u207F = cos n\u03B8 + i sin n\u03B8 \xB7 to multiply, multiply moduli and add arguments \xB7 to find a power, raise the modulus and multiply the argument","Convert to polar form for large powers: find r and \u03B8 first.","(1 + i)\u2078: modulus \u221A2, argument \u03C0/4, so the result has modulus 16 and argument 2\u03C0, i.e. 16."),e("Polar form, De Moivre and roots of unity",1,"Cube roots of unity","\u03C9 = (\u22121 + i\u221A3)/2, \u03C9\xB2 = (\u22121 \u2212 i\u221A3)/2 \xB7 \u03C9\xB3 = 1 \xB7 1 + \u03C9 + \u03C9\xB2 = 0 \xB7 \u03C9\u0304 = \u03C9\xB2 \xB7 \u03C9\u207F depends on n mod 3 \xB7 1 + \u03C9 = \u2212\u03C9\xB2 and 1 + \u03C9\xB2 = \u2212\u03C9","Reduce the power of \u03C9 with n mod 3. Replace 1 + \u03C9 + \u03C9\xB2 by 0 whenever it appears.","1 + \u03C9 + \u03C9\xB2 = 0, so (1 + \u03C9)\u2077 = (\u2212\u03C9\xB2)\u2077 = \u2212\u03C9\xB9\u2074 = \u2212\u03C9\xB2."),e("Polar form, De Moivre and roots of unity",2,"nth roots of unity","the roots of z\u207F = 1 are cos(2k\u03C0/n) + i sin(2k\u03C0/n), k = 0, 1, \u2026, n \u2212 1 \xB7 their sum is 0 \xB7 their product is (\u22121)\u207F\u207A\xB9 \xB7 they lie on the unit circle and form a regular n-gon","Use the sum rule for sums like 1 + \u03C9 + \u03C9\xB2 + \u2026 and the polygon picture for geometry questions.","The 4th roots of unity are 1, i, \u22121, \u2212i and their sum is 0."),e("Locus and geometry",1,"Distance and standard loci","|z \u2212 z\u2081| = distance between z and z\u2081 \xB7 |z \u2212 z\u2080| = r is a circle (centre z\u2080, radius r) \xB7 |z \u2212 z\u2081| = |z \u2212 z\u2082| is the perpendicular bisector \xB7 |z \u2212 z\u2081| + |z \u2212 z\u2082| = k (k > |z\u2081 \u2212 z\u2082|) is an ellipse \xB7 arg((z \u2212 z\u2081)/(z \u2212 z\u2082)) = constant is an arc of a circle \xB7 three points are collinear when (z\u2083 \u2212 z\u2081)/(z\u2082 \u2212 z\u2081) is real","Write z = x + iy and simplify, or read the geometric meaning of the modulus as a distance.","|z \u2212 1| = |z + 1| is the imaginary axis (the perpendicular bisector of 1 and \u22121)."),e("Quadratic equations: roots and nature",1,"Roots, sum and product","ax\xB2 + bx + c = 0 \xB7 x = (\u2212b \xB1 \u221AD)/2a with D = b\xB2 \u2212 4ac \xB7 \u03B1 + \u03B2 = \u2212b/a \xB7 \u03B1\u03B2 = c/a \xB7 equation with roots \u03B1, \u03B2: x\xB2 \u2212 (\u03B1 + \u03B2)x + \u03B1\u03B2 = 0 \xB7 \u03B1\xB2 + \u03B2\xB2 = (\u03B1 + \u03B2)\xB2 \u2212 2\u03B1\u03B2 \xB7 \u03B1\xB3 + \u03B2\xB3 = (\u03B1 + \u03B2)\xB3 \u2212 3\u03B1\u03B2(\u03B1 + \u03B2) \xB7 |\u03B1 \u2212 \u03B2| = \u221AD/|a|","Express the quantity asked in terms of \u03B1 + \u03B2 and \u03B1\u03B2 first, then substitute.","For x\xB2 \u2212 6x + 8 = 0: \u03B1 + \u03B2 = 6, \u03B1\u03B2 = 8, so \u03B1\xB2 + \u03B2\xB2 = 36 \u2212 16 = 20 and the roots are 2 and 4."),e("Quadratic equations: roots and nature",1,"Nature of roots","D > 0: two real distinct roots \xB7 D = 0: equal real roots \xB7 D < 0: two complex conjugate roots (for real a, b, c) \xB7 D a perfect square with rational a, b, c: rational roots \xB7 irrational and complex roots come in conjugate pairs for real or rational coefficients","Find D first. For a parameter k, form D as an expression in k and solve the inequality.","x\xB2 \u2212 6x + 13 = 0 has D = 36 \u2212 52 = \u221216 < 0, so the roots are 3 \xB1 2i."),e("Location of roots and common roots",1,"Common roots and conditions","one common root: eliminate x\xB2 between the two equations to get the common root, then substitute \xB7 both roots common: a\u2081/a\u2082 = b\u2081/b\u2082 = c\u2081/c\u2082 \xB7 roots in a ratio m : n: (m + n)\xB2\xB7ac = mn\xB7b\xB2 \xB7 one root double the other: 2b\xB2 = 9ac \xB7 roots reciprocal: a = c \xB7 roots equal in size and opposite in sign: b = 0","Write the condition in terms of \u03B1 and \u03B2 and then convert to a, b, c using the sum and product.","Roots in ratio 1 : 2 give 2b\xB2 = 9ac, e.g. x\xB2 \u2212 3x + 2 = 0 (roots 1 and 2): 2\xB79 = 18 = 9\xB71\xB72."),e("Location of roots and common roots",2,"Location of roots and sign of a quadratic","for f(x) = ax\xB2 + bx + c with a > 0: both roots greater than k needs D \u2265 0, \u2212b/2a > k and f(k) > 0 \xB7 k between the roots needs f(k) < 0 \xB7 exactly one root in (p, q) needs f(p)\xB7f(q) < 0 \xB7 f(x) > 0 for all real x needs a > 0 and D < 0","Sketch the parabola. Pick out the three things to check: D, the position of the vertex \u2212b/2a, and the sign of f at the given point.","x\xB2 \u2212 4x + 5 > 0 for all x because a = 1 > 0 and D = 16 \u2212 20 = \u22124 < 0.")],look:["i\u2074 = 1; reduce i\u207F by n mod 4; z\xB7z\u0304 = |z|\xB2; |z\u2081z\u2082| = |z\u2081||z\u2082|","1 + \u03C9 + \u03C9\xB2 = 0, \u03C9\xB3 = 1; nth roots of unity sum to 0","|z \u2212 z\u2080| = r circle; |z \u2212 z\u2081| = |z \u2212 z\u2082| perpendicular bisector","x\xB2 \u2212 (sum)x + product = 0; D = b\xB2 \u2212 4ac decides the nature of roots","a > 0 and D < 0 \u21D2 f(x) > 0 for all x"],notes:[{h:"Complex numbers",items:["i\xB2 = \u22121. The powers of i repeat in cycles of 4.","Divide using the conjugate of the denominator.","z\xB7z\u0304 = |z|\xB2 and |z\u2081z\u2082| = |z\u2081||z\u2082|.","Arguments add under multiplication and subtract under division."]},{h:"Roots of unity and loci",items:["The cube roots of 1 are 1, \u03C9, \u03C9\xB2 with 1 + \u03C9 + \u03C9\xB2 = 0.","|z \u2212 z\u2080| = r is a circle; |z \u2212 z\u2081| = |z \u2212 z\u2082| is a straight line.","De Moivre: (cos \u03B8 + i sin \u03B8)\u207F = cos n\u03B8 + i sin n\u03B8."]},{h:"Quadratic equations",items:["Sum of roots = \u2212b/a and product = c/a.","D < 0 gives complex conjugate roots for real coefficients.","For a common root, eliminate the squared term between the two equations."]}],asked:[{t:"Simplify a complex expression or find its modulus and argument",what:"A fraction or power of complex numbers is given. Write it as x + iy, or find |z| and arg z.",steps:["For a quotient multiply top and bottom by the conjugate of the bottom.","Use z\xB7z\u0304 = |z|\xB2 and the rule |z\u2081z\u2082| = |z\u2081||z\u2082|.","For large powers convert to polar form and use De Moivre."],ex:"(1 + i)\u2078 = 16.",tp:"calg"},{t:"Locus of a point z",what:"A condition on |z \u2212 a| or arg is given. Identify the curve.",steps:["Read |z \u2212 a| as a distance from the point a.","Equal distances to two points give a line; a fixed distance gives a circle.","Check by writing z = x + iy when in doubt."],ex:"|z \u2212 1| = |z + 1| is the imaginary axis.",tp:"cpl"},{t:"Roots of unity and powers of \u03C9",what:"An expression in \u03C9, \u03C9\xB2 or in nth roots of unity is given.",steps:["Reduce each power of \u03C9 with n mod 3.","Replace 1 + \u03C9 + \u03C9\xB2 by 0 wherever it appears.","For nth roots of unity use that their sum is 0."],ex:"(1 + \u03C9)\u2077 = \u2212\u03C9\xB2.",tp:"cpl"},{t:"Nature, sum and product of roots",what:"A quadratic with a parameter, or a relation between the roots, is given.",steps:["Write \u03B1 + \u03B2 = \u2212b/a and \u03B1\u03B2 = c/a.","Express the asked quantity through them.","Use D = b\xB2 \u2212 4ac for the nature of the roots or the range of a parameter."],ex:"x\xB2 \u2212 6x + 8 = 0 gives \u03B1\xB2 + \u03B2\xB2 = 20.",tp:"cquad"},{t:"Common roots and location of roots",what:"Two equations share a root, or the roots must lie in a given interval.",steps:["Eliminate the squared term to get the common root and substitute it.","For location use D, the vertex \u2212b/2a and the sign of f at the given point.","Sketch the parabola to avoid missing a case."],ex:"x\xB2 \u2212 4x + 5 > 0 for all x (D < 0, a > 0).",tp:"cquad"}],guide:{intro:"Complex Numbers and Quadratic Equations give 2 to 3 questions in JEE Mains in most years: a simplification or a locus, a power of \u03C9, and a quadratic with a condition on its roots. About 8 hours in 5 days is enough. The chapter is the base for sequences, conics and calculus, so the effort pays again.",plan:[["Day 1 \xB7 90 min","Powers of i, the operations, conjugate and modulus."],["Day 2 \xB7 90 min","Argument, polar form, De Moivre."],["Day 3 \xB7 90 min","Cube and nth roots of unity; locus and geometry."],["Day 4 \xB7 90 min","Quadratic equations: roots, discriminant, sum and product."],["Day 5 \xB7 90 min","Common roots and location of roots; then Most asked and the PYQs."]],basics:["Algebraic identities and factorisation.","Solving linear and quadratic equations.","Trigonometric ratios of standard angles.","Coordinate geometry: distance, circle, line."],path:[{t:"Step 1 \xB7 Complex numbers (Day 1)",d:"Learn the powers of i, the four operations and the conjugate.",ready:"you can write (3 + 4i)/(1 \u2212 2i) in the form x + iy in under a minute.",go:"formulas"},{t:"Step 2 \xB7 Argument and roots of unity (Days 2 and 3)",d:"Learn the polar form, De Moivre and the roots of unity.",ready:"you can find (1 + i)\u2078 and (1 + \u03C9)\u2077 without a calculator.",go:"formulas"},{t:"Step 3 \xB7 Locus (Day 3)",d:"Read |z \u2212 a| as a distance and identify the line or circle.",ready:"you can name the curve for |z \u2212 1| = |z + 1| and |z \u2212 2| = 3.",go:"notes"},{t:"Step 4 \xB7 Quadratic equations (Days 4 and 5)",d:"Use sum, product and the discriminant; then common roots and location.",ready:"you can find \u03B1\xB2 + \u03B2\xB2 from the equation and decide the nature of the roots.",go:"asked"}],think:["In every question ask first: is it algebra, a locus, a root of unity, or a quadratic?","Reduce powers early (n mod 4 for i, n mod 3 for \u03C9).","For roots, express the target through \u03B1 + \u03B2 and \u03B1\u03B2 before you substitute."],watch:["Forgetting the quadrant when finding arg z.","Treating |z|\xB2 as z\xB2.","Using D = b\xB2 \u2212 4ac when the coefficients are not real.","Missing the case D = 0 in a condition on the roots."],myths:[["\u221A(\u2212a)\u221A(\u2212b) = \u221A(ab).","Not for negative numbers: \u221A(\u22121)\u221A(\u22121) = i\xB7i = \u22121, not 1."],["Every quadratic has two real roots.","Real roots need D \u2265 0. D < 0 gives a conjugate pair of complex roots."]]}}})()})();
